package fixture

// Store's methods are siblings too, but each difference here is deliberate.
type Store struct{ data []byte }

func (s *Store) respond(status int)                {}
func (s *Store) logf(format string, value any)     {}
func (s *Store) decode(data []byte, at int) int    { return at }
func (s *Store) convert(members []string) []string { return members }
func next(at int) int                              { return at + 1 }

func (s *Store) Name(at int, membs []string) {
	s.respond(200)
	s.logf("name %s", at)
	s.decode(s.data, at)
	s.convert(membs)
	_ = len(membs)
}

func (s *Store) Size(at int, membs []string) {
	s.respond(200)
	s.logf("size %s", at)
	s.decode(s.data, at)
	s.convert(membs)
	_ = len(membs)
}

func (s *Store) Labels(at int, membs []string) {
	s.respond(200)
	s.logf("labels %s", at)
	s.decode(s.data, at)
	s.convert(membs)
	_ = len(membs)
}

func (s *Store) Values(at int, membs []string) {
	s.respond(200)
	s.logf("values %s", at)
	s.decode(s.data, at)
	s.convert(membs)
	_ = len(membs)
}

// Each line differs from the siblings in a way that is not a slip.
func (s *Store) Drop(at int, members []string, err error) {
	s.respond(204)                // a literal: a different status, not a wrong variable
	s.logf("drop failed %v", err) // the whole call differs, not one argument of it
	raw := next(at)
	moved := next(raw)
	s.decode(s.data, moved)     // computed, in two steps, from the siblings' value
	membs := s.convert(members) // the siblings' value doesn't exist yet
	_ = len(members)            // a builtin's arguments vary with what it's asked
	_ = membs
}

package fixture

import "time"

type Options struct{ Kind string }

type Logger struct{}

func (l Logger) With(key, value string) Logger { return l }

func NewContext(ctx string, log Logger) string { return ctx }

type Writer struct{ Log Logger }

func (w *Writer) record(failed bool, kind, method string, startStorage time.Time) {}

func (w *Writer) Create(ctx string, options *Options) string {
	method := "create"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, log)
	startStorage := time.Now()
	w.record(false, options.Kind, method, startStorage)
	return ctx
}

func (w *Writer) Get(ctx string, options *Options) string {
	method := "get"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, log)
	startStorage := time.Now()
	w.record(false, options.Kind, method, startStorage)
	return ctx
}

func (w *Writer) List(ctx string, options *Options) string {
	method := "list"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, log)
	startStorage := time.Now()
	w.record(false, options.Kind, method, startStorage)
	return ctx
}

func (w *Writer) Update(ctx string, options *Options) string {
	method := "update"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, log)
	startStorage := time.Now()
	w.record(false, options.Kind, method, startStorage)
	return ctx
}

func (w *Writer) Delete(ctx string, name string, options *Options) string {
	method := "delete"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, w.Log)
	startStorage := time.Now()
	w.record(false, name, method, startStorage)
	_ = log
	return ctx
}

func (w *Writer) DeleteCollection(ctx string, options *Options) string {
	method := "delete_collection"
	log := w.Log.With("kind", options.Kind)
	ctx = NewContext(ctx, log)
	startStorage := time.Now()
	w.record(false, options.Kind, method, startStorage)
	go func() {
		startLegacy := time.Now()
		w.record(false, options.Kind, method, startLegacy)
	}()
	return ctx
}
